package in.aicon.pocket;
import android.content.Context;import android.database.Cursor;import java.lang.reflect.Constructor;import java.util.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LedgerControllerTest {
 Context context;LedgerController controller;AccountDirectory directory;String a="1234567890",b="9876543210";List<LedgerController.Status> updates;
 VerifiedDriveAccess identity(String subject)throws Exception{Constructor<VerifiedDriveAccess> c=VerifiedDriveAccess.class.getDeclaredConstructor(String.class,String.class,String.class);c.setAccessible(true);return c.newInstance(subject,subject+"@example.invalid","fake-test-token");}
 @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("hisab-account-directory",0).edit().clear().commit();for(String name:new String[]{"pocket.db",AccountScope.databaseFor(a),AccountScope.databaseFor(b)})context.deleteDatabase(name);directory=new AccountDirectory(context);updates=Collections.synchronizedList(new ArrayList<>());}
 @After public void close(){if(controller!=null)controller.close();}
 void create(LedgerController.Runner runner)throws Exception{controller=new LedgerController(context,Runnable::run,(s,changed)->updates.add(s),Executors.newSingleThreadExecutor(),runner);}
 @Test public void verifiedIdentityNeverSelectsCopiesOrSyncs()throws Exception{create((s,t,v)->{fail();return null;});LedgerSession local=controller.session();local.edit(local.ticket(),(db,c,p)->{c.seed(new String[]{"Food"},new String[]{"Cash"});LedgerSessionTest.transaction(db,"income",12300,"","");});controller.verified(identity(a));assertSame(local,controller.session());assertEquals(LedgerController.State.LOCAL,controller.status().state);controller.selectKnown(a);assertEquals(a,controller.status().subject);assertEquals(LedgerController.State.READY,controller.status().state);assertTrue(controller.session().snapshot(controller.session().ticket()).records.isEmpty());try{local.ticket();fail();}catch(IllegalStateException expected){}controller.selectLocal();controller.session().edit(controller.session().ticket(),(db,c,p)->{try(Cursor row=db.rawQuery("SELECT amount FROM tx",null)){assertTrue(row.moveToFirst());assertEquals(12300,row.getLong(0));}});}
 @Test public void restoringAccountCacheRequiresReconnectAndNeverReusesAnotherToken()throws Exception{create((s,t,v)->{fail();return null;});controller.verified(identity(a));controller.selectKnown(a);controller.close();controller=null;create((s,t,v)->{fail();return null;});assertEquals(a,controller.status().subject);assertEquals(LedgerController.State.OFFLINE,controller.status().state);assertFalse(controller.sync());assertEquals(LedgerController.State.NEEDS_SIGN_IN,controller.status().state);VerifiedDriveAccess other=identity(b);try{controller.reconnected(a,other);fail();}catch(IllegalStateException expected){}try{other.accessToken(b);fail();}catch(DriveAppData.NeedsSignIn expected){}assertEquals(a,controller.status().subject);assertEquals(1,controller.accounts().size());controller.reconnected(a,identity(a));assertEquals(LedgerController.State.READY,controller.status().state);}
 @Test public void staleNetworkCompletionCannotRepaintClosedController()throws Exception{CountDownLatch entered=new CountDownLatch(1),finish=new CountDownLatch(1),done=new CountDownLatch(1);create((s,t,v)->{entered.countDown();while(true){try{finish.await();break;}catch(InterruptedException e){}}done.countDown();return new SyncEngine.Result(0,0,0);});controller.verified(identity(a));controller.selectKnown(a);assertTrue(controller.sync());assertTrue(entered.await(10,TimeUnit.SECONDS));try{controller.selectLocal();fail();}catch(IllegalStateException expected){}int events=updates.size();controller.close();finish.countDown();assertTrue(done.await(10,TimeUnit.SECONDS));Thread.sleep(100);assertEquals(events,updates.size());assertEquals(a,directory.selectedSubject());}
 @Test public void forgetDoesNotDeleteCloudOrMoveCachedLedger()throws Exception{create((s,t,v)->{fail();return null;});controller.verified(identity(a));controller.selectKnown(a);controller.forget(a);assertEquals(LedgerController.State.LOCAL,controller.status().state);assertNull(directory.selectedSubject());assertTrue(controller.accounts().isEmpty());assertTrue(context.getDatabasePath(AccountScope.databaseFor(a)).exists());}
 void awaitState(LedgerController.State desired)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(controller.status().state!=desired&&System.nanoTime()<until)Thread.sleep(10);assertEquals(desired,controller.status().state);}
 @Test public void disconnectRevokesExactAccountThenReturnsLocalWithoutErasingCachedMoney()throws Exception{create((s,t,v)->{fail();return null;});VerifiedDriveAccess access=identity(a);controller.verified(access);controller.selectKnown(a);LedgerSession chosen=controller.session();chosen.edit(chosen.ticket(),(db,c,p)->{c.seed(new String[]{"Food"},new String[]{"Cash"});LedgerSessionTest.transaction(db,"income",12300,"","");});CountDownLatch called=new CountDownLatch(1);controller.disconnect(a,(c,e)->{assertEquals(a,e.subject);assertTrue(new AccountDirectory(c).disconnectPending(a));try{access.accessToken(a);fail();}catch(DriveAppData.NeedsSignIn expected){}called.countDown();});assertTrue(called.await(10,TimeUnit.SECONDS));awaitState(LedgerController.State.LOCAL);assertNull(directory.find(a));assertNull(directory.selectedSubject());assertFalse(directory.disconnectPending(a));assertTrue(context.getDatabasePath(AccountScope.databaseFor(a)).exists());}
 @Test public void failedDisconnectPersistsAndBlocksReauthorizationUntilExplicitRetry()throws Exception{create((s,t,v)->{fail();return null;});controller.verified(identity(a));controller.selectKnown(a);CountDownLatch failed=new CountDownLatch(1);controller.disconnect(a,(c,e)->{failed.countDown();throw new java.io.IOException("offline");});assertTrue(failed.await(10,TimeUnit.SECONDS));Thread.sleep(100);assertTrue(directory.disconnectPending(a));assertFalse(controller.sync());assertEquals(LedgerController.State.DISCONNECT_PENDING,controller.status().state);controller.close();controller=null;create((s,t,v)->{fail();return null;});assertEquals(LedgerController.State.DISCONNECT_PENDING,controller.status().state);try{controller.verified(identity(a));fail();}catch(IllegalStateException expected){}controller.disconnect(a,(c,e)->{});awaitState(LedgerController.State.LOCAL);}
 @Test public void staleDisconnectTargetCannotRevokeAnotherSelectedAccount()throws Exception{create((s,t,v)->{fail();return null;});controller.verified(identity(a));controller.selectKnown(a);controller.verified(identity(b));controller.selectKnown(b);try{controller.disconnect(a,(c,e)->fail());fail();}catch(IllegalStateException expected){}assertEquals(b,controller.status().subject);assertFalse(directory.disconnectPending(a));assertFalse(directory.disconnectPending(b));}

}
